def mask_of(rec):
    for k in ("completion_mask", "mask", "loss_mask"):
        if k in rec:
            return rec[k].astype(bool)
    raise KeyError("no mask field")

def ids_of(rec):
    for k in ("completion_ids", "ids"):
        if k in rec:
            return rec[k]
    return None

# ---------- per-row stats for ALL 48 batches ----------
print("\n=== per-row old-vs-cur stats (all batches) ===")
print(f"{'row':>7} {'masklen':>7} {'ndiff':>5} {'mdiff':>5} {'udiff':>5} {'max|d|':>9} {'unm_agree':>9}")
for b, rec in enumerate(recs):
    m = mask_of(rec)
    for r in range(rec["logps"].shape[0]):
        cur, old = rec["logps"][r], rec["old_logps"][r]
        d = cur != old
        nd = int(d.sum()); md = int((d & m[r]).sum()); ud = nd - md
        mx = float(np.abs(cur.astype(np.float64) - old.astype(np.float64))[d].max()) if nd else 0.0
        unm = ~m[r]
        ua = float((cur[unm] == old[unm]).mean()) if unm.sum() else float('nan')
        print(f"b{b:02d}r{r} {int(m[r].sum()):7d} {nd:5d} {md:5d} {ud:5d} {mx:9.4f} {ua:9.3f}")

# ---------- cross-match: whose cur does each old match? ----------
def agree(x, y, mx, my, tol):
    common = mx & my
    n = int(common.sum())
    if n < 20:
        return None, n
    return float((np.abs(x[common].astype(np.float64) - y[common].astype(np.float64)) < tol).mean()), n

allrows = []
for b, rec in enumerate(recs):
    m = mask_of(rec)
    ids = ids_of(rec)
    for r in range(rec["logps"].shape[0]):
        allrows.append(dict(b=b, r=r, cur=rec["logps"][r], old=rec["old_logps"][r],
                             m=m[r], ids=(ids[r] if ids is not None else None)))

print("\n=== old(row) -> best matching cur(row), search over batches 0..15 (frozen weights) ===")
for i, row in enumerate(allrows[:8]):  # window-0 rows
    scored = []
    for j, cand in enumerate(allrows[:16]):
        a, n = agree(row["old"], cand["cur"], row["m"], cand["m"], 1e-4)
        if a is not None:
            scored.append((a, cand["b"], cand["r"], n))
    scored.sort(reverse=True)
    print(f"old(b{row['b']}r{row['r']}): " + "  ".join(f"b{b}r{r}:{a:.2f}(n={n})" for a, b, r, n in scored[:5]))

print("\n=== old-vs-old duplication within window 0 ===")
w0 = allrows[:8]
for i in range(8):
    for j in range(8):
        if i == j: continue
        a, n = agree(w0[i]["old"], w0[j]["old"], w0[i]["m"], w0[j]["m"], 1e-4)
        if a is not None and a > 0.3:
            print(f"old(b{w0[i]['b']}r{w0[i]['r']}) ~= old(b{w0[j]['b']}r{w0[j]['r']}): agree={a:.3f} common={n}")

# ---------- shared-prefix analysis on completion ids ----------
if w0[0]["ids"] is not None:
    print("\n=== completion_ids shared-prefix matrix (window 0), and prompt groups ===")
    def pref(a, b):
        n = min(len(a), len(b))
        i = 0
        while i < n and a[i] == b[i]:
            i += 1
        return i
    for i in range(8):
        for j in range(i + 1, 8):
            p = pref(w0[i]["ids"], w0[j]["ids"])
            if p > 0:
                print(f"rows (b{w0[i]['b']}r{w0[i]['r']}) & (b{w0[j]['b']}r{w0[j]['r']}): shared prefix {p} tokens")
