import base64, hashlib, os, sys

DIST = "/usr/local/lib/python3.10/dist-packages"
CRITICAL = ["transformers", "accelerate", "datasets", "peft", "trl"]
found = {}
for d in os.listdir(DIST):
    if d.endswith(".dist-info"):
        for c in CRITICAL:
            if d.lower().startswith(c + "-"):
                found.setdefault(c, []).append(d)

def parse_record(rec):
    entries = {}
    for line in open(rec, encoding="utf-8"):
        line = line.rstrip("\n")
        if not line or line.startswith("#"):
            continue
        parts = line.split(",")
        if len(parts) >= 2 and parts[1].startswith("sha256="):
            entries[parts[0]] = parts[1][len("sha256="):]
    return entries

def sha256_file(p):
    h = hashlib.sha256()
    with open(p, "rb") as f:
        for chunk in iter(lambda: f.read(1 << 22), b""):
            h.update(chunk)
    return base64.urlsafe_b64encode(h.digest()).decode().rstrip("=")

for pkg in CRITICAL:
    infos = found.get(pkg)
    if not infos:
        print(f"{pkg}: NOT INSTALLED (via RECORD)")
        continue
    for name in sorted(infos):
        rec = os.path.join(DIST, name, "RECORD")
        if not os.path.exists(rec):
            print(f"{name}: no RECORD")
            continue
        entries = parse_record(rec)
        bad, missing, checked = [], [], 0
        for path, expect in entries.items():
            full = os.path.join(DIST, path)
            if not os.path.exists(full):
                missing.append(path)
                continue
            got = sha256_file(full)
            checked += 1
            if got != expect.rstrip("="):
                bad.append(path)
        print(f"{name}: {checked} files hash-verified, {len(missing)} missing, {len(bad)} MISMATCHES")
        for p in bad[:10]:
            print(f"    MISMATCH: {p}")
        for p in missing[:5]:
            print(f"    missing: {p}")
